using System;using System.IO;using System.Reflection;using System.Collections;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class DenseBattleCheck{
 public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");g.SetPaused(true);var f=BindingFlags.Instance|BindingFlags.NonPublic;var list=(IList)typeof(RunSimulator).GetField("enemies",f).GetValue(g.Run);list.Clear();for(int i=0;i<80;i++){var e=new EnemyState();Set(e,"Id",10000+i);Set(e,"Kind",(EnemyKind)(i%5));Set(e,"X",(double)(-320+(i%10)*70));Set(e,"Y",(double)(-240+(i/10)*76));Set(e,"Hp",10d);Set(e,"MaxHp",10d);list.Add(e);}var w=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",f).GetValue(g);w.Reset(g.Run);g.PresentBattle();if(w.ActiveEnemies!=80)throw new Exception("Missing enemies");var root=(GameObject)typeof(InkBattleWorld).GetField("root",f).GetValue(w);int initial=root.GetComponentsInChildren<SpriteRenderer>(true).Length;for(int n=0;n<20;n++)g.PresentBattle();int after=root.GetComponentsInChildren<SpriteRenderer>(true).Length;if(after!=initial)throw new Exception("Renderer growth without ticks");var result=new{passed=true,enemies=w.ActiveEnemies,rendererBefore=initial,rendererAfter=after,renderCalls=20,scope="Artificial 80-enemy five-kind static fixture; not balance, performance or natural wave evidence"};File.WriteAllText(Path.GetFullPath("../docs/evidence/dense-battle-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/dense-battle-check.png"));return result;}
 static void Set(EnemyState e,string name,object value){typeof(EnemyState).GetProperty(name).SetValue(e,value);}
}

